"use client";
import { useState } from "react";
import { Deck, Card } from "../types";
import { addCard, deleteCard, drawCard } from "../api/api";

interface Props {
  deck: Deck;
  onUpdate: (deck: Deck) => void;
  onBack: () => void;
}

type ModalType = "draw" | "add" | null;

export default function DeckView({ deck, onUpdate, onBack }: Props) {
  const [activeModal, setActiveModal] = useState<ModalType>(null);
  const [drawnCard, setDrawnCard] = useState<Card | null>(null);
  const [newActivity, setNewActivity] = useState("");
  const [newDescription, setNewDescription] = useState("");
  const [newOutdoor, setNewOutdoor] = useState(false);
  const [cardToDelete, setCardToDelete] = useState<Card | null>(null);

  const handleDraw = async (outdoor: boolean | null = null) => {
    const result = await drawCard(deck.id, outdoor);
    if (result == null) return;
    setDrawnCard(result);
  };

  const handleAddCard = async () => {
    if (newActivity.trim() === "") return;
    const newCard = await addCard(deck.id, { activity: newActivity, outdoor: newOutdoor, description: newDescription });
    const updatedDeck = { ...deck, cards: [...deck.cards, newCard] };
    onUpdate(updatedDeck);
    setNewActivity("");
    setNewDescription("");
    setNewOutdoor(false);
  };

  const confirmDelete = async () => {
    if (!cardToDelete) return;
    await deleteCard(deck.id, cardToDelete.id);
    const updatedDeck = { ...deck, cards: deck.cards.filter((c) => c.id !== cardToDelete.id) };
    onUpdate(updatedDeck);
    setCardToDelete(null);
  };

  const closeModal = () => {
    setActiveModal(null);
    setDrawnCard(null);
  };

  return (
    <div className="max-w-2xl mx-auto mt-16 px-4">
      <button onClick={onBack} className="text-[#7a77c8] hover:text-[#2a2d4a] mb-4 font-semibold transition-colors">
        ← Back
      </button>
      <h1 className="text-4xl font-bold mb-8 text-[#2a2d4a]">{deck.name}</h1>

      {/* Action buttons */}
      <div className="flex gap-4 mb-10">
        <button
          onClick={() => setActiveModal("draw")}
          className="flex-1 bg-[#7a77c8] text-[#e9e6ff] font-bold py-3 rounded-xl hover:bg-[#b6b3f2] hover:text-[#2a2d4a] transition-all">
          ꩜ Draw a card
        </button>
        <button
          onClick={() => setActiveModal("add")}
          className="flex-1 bg-[#7a77c8] text-[#e9e6ff] font-bold py-3 rounded-xl hover:bg-[#b6b3f2] hover:text-[#2a2d4a]  transition-all">
          + Add a card
        </button>
      </div>

      {/* Draw / Add modal — click backdrop to close, click inside stays open */}
      {activeModal && (
        <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50 px-4" onClick={closeModal}>
          <div className="bg-[#e9e6ff] rounded-2xl p-6 w-full max-w-md shadow-xl relative" onClick={(e) => e.stopPropagation()}>
            <button
              onClick={closeModal}
              className="absolute top-3 right-4 text-[#7a77c8] hover:text-[#2a2d4a] text-xl font-bold">
              ✕
            </button>

            {activeModal === "draw" && (
              <div>
                <h2 className="text-2xl font-bold text-[#2a2d4a] mb-4">Draw a Card</h2>
                {drawnCard ? (
                  <div className="mb-4 bg-[#2a2d4a] rounded-xl p-4">
                    <p className="text-lg font-semibold text-[#e9e6ff]">{drawnCard.activity}</p>
                    <p className="text-[#b6b3f2]">{drawnCard.description}</p>
                  </div>
                ) : (
                  <p className="text-[#7a77c8] mb-4">Choose your mode!</p>
                )}
                <div className="flex gap-3 flex-wrap">
                  <button onClick={() => handleDraw(null)}
                    className="bg-[#7a77c8] text-[#e9e6ff] font-bold px-5 py-2 rounded-xl hover:bg-[#b6b3f2] hover:text-[#2a2d4a] transition-all">
                    Any
                  </button>
                  <button onClick={() => handleDraw(true)}
                    className="bg-[#7a77c8] text-[#e9e6ff] font-bold px-5 py-2 rounded-xl hover:bg-[#b6b3f2] hover:text-[#2a2d4a] transition-all">
                    Outdoor
                  </button>
                  <button onClick={() => handleDraw(false)}
                    className="bg-[#7a77c8] text-[#e9e6ff] font-bold px-5 py-2 rounded-xl hover:bg-[#b6b3f2] hover:text-[#2a2d4a] transition-all">
                    Indoor
                  </button>
                </div>
              </div>
            )}

            {activeModal === "add" && (
              <div>
                <h2 className="text-2xl font-bold text-[#2a2d4a] mb-4">Add a Card</h2>
                <div className="flex flex-col gap-3">
                  <input
                    type="text"
                    placeholder="New card activity..."
                    value={newActivity}
                    onChange={(e) => setNewActivity(e.target.value)}
                    onKeyDown={(e) => e.key === "Enter" && handleAddCard()}
                    className="rounded-xl px-4 py-3 bg-white text-[#2a2d4a] placeholder-[#7a77c8] outline-none focus:ring-2 focus:ring-[#7a77c8]"
                  />
                  <input
                    type="text"
                    placeholder="Add a description..."
                    value={newDescription}
                    onChange={(e) => setNewDescription(e.target.value)}
                    onKeyDown={(e) => e.key === "Enter" && handleAddCard()}
                    className="rounded-xl px-4 py-3 bg-white text-[#2a2d4a] placeholder-[#7a77c8] outline-none focus:ring-2 focus:ring-[#7a77c8]"
                  />
                  <label className="flex items-center gap-2 text-[#2a2d4a]">
                    <input type="checkbox" checked={newOutdoor} onChange={(e) => setNewOutdoor(e.target.checked)} />
                    Outdoor activity?
                  </label>
                  <button onClick={handleAddCard}
                    className="bg-[#7a77c8] text-[#e9e6ff] font-bold px-6 py-3 rounded-xl hover:bg-[#b6b3f2] hover:text-[#2a2d4a] transition-all self-start">
                    + Create
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Delete confirmation modal */}
      {cardToDelete && (
        <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50 px-4" onClick={() => setCardToDelete(null)}>
          <div className="bg-[#e9e6ff] rounded-2xl p-6 w-full max-w-sm shadow-xl" onClick={(e) => e.stopPropagation()}>
            <h2 className="text-xl font-bold text-[#2a2d4a] mb-2">Delete card?</h2>
            <p className="text-[#7a77c8] mb-1">
              "{cardToDelete.activity}" will be permanently removed.
            </p>
            <p className="text-[#D9789E] text-sm font-semibold mb-6">Warning: this cannot be undone.</p>
            <div className="flex gap-3 justify-end">
              <button onClick={() => setCardToDelete(null)}
                className="px-5 py-2 rounded-xl font-semibold text-[#2a2d4a] hover:bg-[#c7d6ff] transition-all">
                Cancel
              </button>
              <button onClick={confirmDelete}
                className="bg-[#D9789E] text-white font-bold px-5 py-2 rounded-xl hover:bg-[#C15D85] transition-all">
                Delete
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Card list */}
      <section className="flex flex-col gap-3">
        {deck.cards.length === 0 ? (
          <p className="text-[#7a77c8] text-center">no cards yet...</p>
        ) : (
          deck.cards.map((card) => (
            <div key={card.id}
              className="flex items-center justify-between bg-[#2a2d4a] hover:bg-[#353853] border border-[#7a77c8] rounded-xl px-5 py-3 shadow-sm">
              <div>
                <p className="font-semibold text-[#e9e6ff]">{card.activity}</p>
                <p className="text-sm text-[#b6b3f2]">{card.description}</p>
              </div>
              <button onClick={() => setCardToDelete(card)}
                className="text-[#7a77c8] hover:text-[#D9789E] transition-colors text-xl px-2">
                ✕
              </button>
            </div>
          ))
        )}
      </section>
    </div>
  );
}